export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    // JavaScript validation
    if (!name || !email || !message) {
      throw new Error('All fields are required');
    }

    // Simulate saving the contact message
    console.log('Contact message received:', { name, email, message });
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitContact} style={{ display: 'flex', flexDirection: 'column', gap: '1rem', maxWidth: '400px' }}>
        <div>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '0.5rem' }}>Name</label>
          <input type="text" id="name" name="name" required style={{ width: '100%', padding: '0.5rem' }} />
        </div>

        <div>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '0.5rem' }}>Email</label>
          <input type="email" id="email" name="email" required style={{ width: '100%', padding: '0.5rem' }} />
        </div>

        <div>
          <label htmlFor="message" style={{ display: 'block', marginBottom: '0.5rem' }}>Message</label>
          <textarea id="message" name="message" rows={4} required style={{ width: '100%', padding: '0.5rem' }} />
        </div>

        <button type="submit" style={{ padding: '0.75rem', backgroundColor: '#0070f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
          Send Message
        </button>
      </form>
    </div>
  );
}

